// Pega o CSV como texto vindo do HTTP Request
const csvRaw = $json.data ?? $json.body ?? $json;
const text = (typeof csvRaw === "string") ? csvRaw :
JSON.stringify(csvRaw);

const lines = text.split(/\r?\n/).map(l => l.trim()).filter(Boolean);
const headers = lines[0].split(",").map(h => h.trim());

const investimentos = lines.slice(1).map(line => {
  const cols = line.split(",").map(c => c.trim());
  const obj = {};
  headers.forEach((h, i) => obj[h] = cols[i] ?? "");

  // normaliza mínimo para número
  obj.minimo = Number(String(obj.minimo).replace(/[^\d]/g, "")) || 0;

  return obj;
});

return [{ json: { investimentos } }];

// 1. Obtém os investimentos gerados no fluxo anterior
const investimentos = $json.investimentos ?? $("Code in JavaScript").first().json.investimentos ?? [];

// 2. Obtém os clientes recebidos pelo Webhook
const webhookData = $("Webhook").first().json;
let clientes = webhookData.body?.clientes ?? webhookData.body ?? webhookData.clientes ?? webhookData;

// Se os clientes vierem como texto CSV pelo Webhook ou array
if (typeof clientes === "string" && clientes.includes("\n")) {
  const cLines = clientes.split(/\r?\n/).map(l => l.trim()).filter(Boolean);
  const cHeaders = cLines[0].split(",").map(h => h.trim());
  clientes = cLines.slice(1).map(line => {
    const cols = line.split(",").map(c => c.trim());
    const o = {};
    cHeaders.forEach((h, i) => o[h] = cols[i] ?? "");
    return o;
  });
} else if (!Array.isArray(clientes)) {
  clientes = $("Webhook").all().map(item => item.json.body ?? item.json);
}

// 3. Função pick para selecionar aleatoriamente uma mensagem
function pick(array) {
  if (!array || array.length === 0) return "";
  return array[Math.floor(Math.random() * array.length)];
}

// 4. Mapeamento e recomendações para cada cliente
const resultados = clientes.map(c => {
  const nome = c.Nome ?? c.nome ?? "";
  const email = c.Email ?? c.email ?? "";
  const perfil = c.Perfil ?? c.perfil ?? "";
  const saldoTexto = c.Saldo ?? c.saldo ?? "";

  // Extrai o valor numérico inteiro (ex: "R$ 12.500,00" -> 12500)
  const saldoLimpo = String(saldoTexto).split(",")[0].replace(/[^\d]/g, "");
  const saldoNum = Number(saldoLimpo) || 0;

  // Filtra opções pelo perfil do cliente
  const opcoesPerfil = investimentos.filter(inv => 
    String(inv.perfil).toLowerCase() === String(perfil).toLowerCase()
  );

  // Filtra opções em que o saldo cobre o aporte mínimo
  const compativeis = opcoesPerfil.filter(inv => saldoNum >= inv.minimo);

  let escolhido = null;
  let motivo = "saldo_ok";

  if (compativeis.length > 0) {
    // Escolhe a opção que melhor aproveita o saldo disponível
    escolhido = compativeis.reduce((prev, curr) => (curr.minimo >= prev.minimo ? curr : prev), compativeis[0]);
  } else if (opcoesPerfil.length > 0) {
    escolhido = opcoesPerfil[0];
    motivo = "saldo_insuficiente";
  }

  // Gera as variações de mensagens
  const mensagens = [];
  if (escolhido) {
    const minFormatado = `R$ ${escolhido.minimo.toLocaleString("pt-BR")},00`;

    if (motivo === "saldo_ok") {
      mensagens.push(
        `Olá ${nome}! Pelo seu perfil (${perfil}), uma boa opção é **${escolhido.produto}** (mínimo ${minFormatado}). Com seu saldo atual (${saldoTexto}), você já consegue investir. Rentabilidade: ${escolhido.rentabilidade}.`,
        `Oi ${nome}! Recomendação para perfil ${perfil}: **${escolhido.produto}** (mínimo ${minFormatado}). Seu saldo (${saldoTexto}) já atende o mínimo. Rentabilidade: ${escolhido.rentabilidade}.`,
        `${nome}, indo direto ao ponto: para o perfil ${perfil}, **${escolhido.produto}** (mínimo ${minFormatado}). Você tem ${saldoTexto}, então dá pra aplicar. Rentabilidade: ${escolhido.rentabilidade}.`
      );
    } else {
      mensagens.push(
        `Olá ${nome}! Pelo seu perfil (${perfil}), indicamos **${escolhido.produto}** (mínimo ${minFormatado}), mas no momento seu saldo (${saldoTexto}) ainda não atinge o aporte mínimo.`
      );
    }
  }

  return {
    nome,
    email,
    perfil,
    saldo_texto: saldoTexto,
    saldo_num: saldoNum,
    recomendacao: escolhido,
    motivo,
    mensagens,
    mensagem_escolhida: pick(mensagens),
  };
});

// 5. Retorno final exatamente como demonstrado na aula
return [{
  json: {
    ok: true,
    total_clientes: resultados.length,
    total_investimentos: investimentos.length,
    resultados
  }
}];

const resultados = $json.resultados || [];

function parseBRL(valor) {
  if (!valor) return 0;
  const s = String(valor)
    .replace("R$", "")
    .replace(/\./g, "")
    .replace(",", ".")
    .replace(/[^\d.]/g, "")
    .trim();
  const n = Number(s);
  return Number.isFinite(n) ? n : 0;
}

// retorna UM ITEM por cliente
const out = resultados.map(c => {
  const saldoNum = c.saldo_num ?? parseBRL(c.saldo_texto ?? c.saldo);

  return {
    json: {
      email_to: String(c.email || "").trim(),
      nome: String(c.nome || "").trim(),
      perfil: c.perfil,
      saldo_texto: c.saldo_texto ?? c.saldo,
      saldo_num: saldoNum,
      recomendacao: c.recomendacao,
      motivo: c.motivo,
      mensagem_base: c.mensagem_escolhida || c.mensagem || "",
      copy_rules: {
        idioma: "pt-BR",
        tom: "amigável e profissional",
        tamanho: "curto (4-6 linhas)",
        evitar: ["promessas de ganho", "garantias", "linguagem agressiva"]
      }
    }
  };
});

return out;

