// Obtém todos os itens que chegam do nó anterior (AI Agent)
const items = $input.all();

return items.map(item => {
  const j = item.json;

  // 1. Identifica a resposta gerada pela IA (seja output, text, response ou o próprio j)
  let rawAiOutput = j.output ?? j.text ?? j.response?.text ?? j.response ?? "";
  let aiData = {};

  if (typeof rawAiOutput === "string") {
    // Remove possíveis blocos de formatação markdown como ```json e ```
    const cleaned = rawAiOutput
      .replace(/```json/gi, "")
      .replace(/```/g, "")
      .trim();

    try {
      aiData = JSON.parse(cleaned);
    } catch (e) {
      // Caso a IA não tenha retornado um JSON válido, usa o texto bruto
      aiData = {
        subject: "Sugestão de Investimento",
        text_body: rawAiOutput,
        html_body: `<p>${rawAiOutput.replace(/\n/g, "<br>")}</p>`
      };
    }
  } else if (typeof rawAiOutput === "object" && rawAiOutput !== null) {
    aiData = rawAiOutput;
  }

  // 2. Extrai e normaliza os campos para o envio do Gmail
  const to = j.email ?? j.Email ?? j.to ?? "";
  const subject = aiData.subject ?? j.subject ?? "Oportunidade de Investimento";
  const text_body = aiData.text_body ?? j.text_body ?? "";

  // Se não houver html_body definido, converte as quebras de linha do text_body em parágrafos/br
  const html_body = aiData.html_body ?? j.html_body ?? (
    text_body ? `<p>${text_body.replace(/\n\s*\n/g, "</p><p>").replace(/\n/g, "<br>")}</p>` : ""
  );

  // 3. Retorno no formato exato da aula
  return {
    json: {
      ok: true,
      to,
      subject,
      text_body,
      html_body,

      // (opcional) manter alguns campos úteis pra debug/aula
      meta: {
        nome: j.nome,
        perfil: j.perfil,
        produto: j.recomendacao?.produto,
        minimo: j.recomendacao?.minimo,
        rentabilidade: j.recomendacao?.rentabilidade,
        motivo: j.motivo
      }
    }
  };
});
